import assert from 'node:assert/strict'
import { join } from 'node:path'
import { DatabaseSync } from 'node:sqlite'
import { setImmediate } from 'node:timers/promises'
import { test } from 'node:test'
import { fixture, main, outsider, ownerSource, relaySource, reviewer, until, worker } from './host-fixture.mjs'

const exactTitle = '00-main'
const question = '做了那些事情'
const exactInput = '你问一下' + exactTitle + question
const modelText = '[model changed: assistant turns above this point were generated by deepseek-v4-flash; the session continues with deepseek-v4-pro]'
const modelSelection = { kind: 'model-selection', form: 'notice', summary: 'deepseek-v4-flash → deepseek-v4-pro' }

async function completedQuestion(host, owner, target, goal) {
  const notice = await host.receive(target)
  assert.equal(notice.source.bridgeWorkflowKind, 'task')
  assert.equal(notice.source.senderSessionId, owner)
  const id = notice.source.bridgeWorkflowId
  const claim = await host.call(target, 'workflow_claim', { id })
  assert.equal(claim.owner, owner)
  assert.equal(claim.goal, goal)
  assert.equal(claim.instructions, goal)
  const summary = '合成原窗回报。'
  const report = await host.call(target, 'workflow_report', {
    id, attempt: claim.attempt, token: claim.token, status: 'completed', summary, evidence: ['synthetic-autonomy'],
  })
  assert.equal(report.duplicate, false)
  host.end(target)
  const result = await host.receive(owner)
  assert.equal(result.source.bridgeWorkflowKind, 'result')
  assert.equal(result.source.bridgeWorkflowId, id)
  assert.equal(result.source.bridgeWorkflowOwner, owner)
  assert(result.content[0].text.includes(summary))
  host.end(owner)
  await until(async () => {
    host.begin(owner, '核对合成原窗的任务。')
    const state = await host.call(owner, 'workflow_status', { task: claim.task })
    host.end(owner)
    return state.state === 'closed'
  }, 'Expected the task to close after the native result')
  assert.deepEqual(host.deliveries.map(({ target }) => target), [target, owner])
}

test('an exact named question is sent once despite repeated calls to the unified entry', async t => {
  const host = await fixture(t)
  assert(host.tools.has('workflow_message'))
  assert(!host.tools.has('send_session_message'))
  assert(!host.tools.has('send_natural_session_message'))
  assert(!host.tools.has('workflow_delegate_direct'))
  host.rename(main, exactTitle)
  host.begin(worker, exactInput)
  const observe = () => host.call(worker, 'workflow_message', {})
  assert.deepEqual(await observe(), { state: 'waiting_for_owner_turn_end' })
  assert.deepEqual(await observe(), { state: 'waiting_for_owner_turn_end' })
  assert.deepEqual(host.deliveries, [])
  host.end(worker)
  await completedQuestion(host, worker, main, question)
})

test('the original owner text remains authoritative over mismatched arguments to the unified entry', async t => {
  const host = await fixture(t)
  host.rename(main, exactTitle)
  host.begin(worker, exactInput)
  const refused = await host.call(worker, 'workflow_message', {
    to: outsider, request_id: 'synthetic-mismatched-legacy', text: '不得成为委托任务的合成正文',
  })
  assert.equal(refused.error, 'workflow_message_invalid_arguments')
  assert.deepEqual(host.deliveries, [])
  host.end(worker)
  await completedQuestion(host, worker, main, question)
})

test('an exact owner command with an unquoted full title and read-only suffix is dispatched and returned by the host', async t => {
  const host = await fixture(t)
  host.rename(worker, '99-运维')
  const goal = '检查目前电脑状态，不要做任何修改'
  host.begin(main, '你让99-运维' + goal)
  host.appendInput(main, modelText, modelSelection)
  assert.deepEqual(host.deliveries, [])
  host.end(main)

  const assignment = await host.receive(worker)
  const job = assignment.source.bridgeWorkflowId
  assert.equal(assignment.source.bridgeWorkflowKind, 'task')
  assert.equal(assignment.source.senderSessionId, main)
  assert(assignment.content.some(({ text }) => text === goal))
  const answer = '合成只读核对完成。'
  host.reply(worker, answer)
  host.end(worker)

  const result = await host.receive(main)
  assert.equal(result.source.bridgeWorkflowKind, 'conversation')
  assert.equal(result.source.bridgeWorkflowId, job)
  assert(result.content.some(({ text }) => text.endsWith(answer)))
  host.end(main)
  assert.deepEqual(host.deliveries.map(({ target }) => target), [worker, main])
})

