test('a native model-selection notice keeps the exact owner turn eligible for one direct question', async t => {
  const host = await fixture(t)
  host.rename(worker, '合成查询')
  host.begin(main, '你给合成查询这个窗口问他今天气温怎么样')
  host.appendInput(main, modelText, modelSelection)
  host.end(main)
  await completedQuestion(host, main, worker, '今天气温怎么样')
})

for (const [name, source] of [['owner', ownerSource], ['relay', relaySource]]) {
  test('model-switch text from an additional ' + name + ' input cannot preserve the owner-turn authority', async t => {
    const host = await fixture(t)
    host.rename(worker, '合成查询')
    host.begin(main, '你给合成查询这个窗口问他今天气温怎么样')
    host.appendInput(main, modelText, source)
    host.end(main)
    await setImmediate()
    assert.deepEqual(host.deliveries, [])
  })
}

for (const name of ['archived', 'unknown']) {
  test('an ' + name + ' longer title cannot authorize a shorter-prefix assignment', async t => {
    const host = await fixture(t)
    host.rename(worker, '合成审核')
    if (name === 'archived') {
      host.rename(outsider, '合成审核备用')
      host.archive(outsider)
    }
    const ledger = new DatabaseSync(join(process.env.DSH_HOME, 'profile', 'dsh-session-bridge-workflow', 'workflow-v1.sqlite'))
    t.after(() => ledger.close())

    host.begin(main, '你问一下合成审核备用窗口多大内存够用')
    host.end(main)
    await setImmediate()
    const state = JSON.parse(ledger.prepare('SELECT body FROM ledger').get().body)
    assert.deepEqual(state.grants, {})
    assert.deepEqual(state.jobs, {})
    assert.equal(host.deliveries.filter(({ message }) => message.source.bridgeWorkflowKind === 'task').length, 0)
  })
}

test('an explicitly named message cannot enter another active task through the unified entry', async t => {
  const host = await fixture(t)
  host.rename(worker, '合成甲审')
  host.rename(reviewer, '合成乙审')
  for (const [target, title] of [[worker, '合成甲审'], [reviewer, '合成乙审']]) {
    host.begin(main, '让「' + title + '」窗口核对合成项目')
    host.end(main)
    const assignment = await host.receive(target)
    assert.equal(assignment.source.bridgeWorkflowKind, 'task')
    assert.equal((await host.call(target, 'workflow_claim', { id: assignment.source.bridgeWorkflowId })).duplicate, false)
    host.end(target)
  }

  const text = '只读核对甲项的合成补充。'
  host.begin(main, '补充一条合成消息。')
  const unbound = await host.call(main, 'workflow_message', { target: reviewer, text })
  assert.equal(unbound.error, 'workflow_task_reference_required')
  host.end(main)
  host.begin(main, '请给合成甲审窗口发消息：' + text)
  const refused = await host.call(main, 'workflow_message', {
    to: reviewer, request_id: 'synthetic-wrong-ordinary-target', text,
  })
  assert.equal(refused.error, 'workflow_message_invalid_arguments')
  const observation = await host.call(main, 'workflow_message', {
    target: reviewer, text: '这段模型改写不得入队。',
  })
  assert.deepEqual(observation, { state: 'waiting_for_owner_turn_end' })
  host.end(main)
  const chosen = await host.receive(worker)
  assert.equal(chosen.source.bridgeWorkflowKind, 'conversation')
  assert(chosen.content[0].text.endsWith(text))
  host.end(worker)
  assert(!host.deliveries.some(({ target, message }) => target === reviewer &&
    message.content.some(({ text: body }) => body?.endsWith(text))))
  assert(!host.deliveries.some(({ message }) =>
    message.content.some(({ text: body }) => body?.endsWith('这段模型改写不得入队。'))))
})

test('the unified entry keeps a named follow-up and its plain reply in the selected active task', async t => {
  const host = await fixture(t)
  host.rename(worker, '合成甲审')
  host.rename(reviewer, '合成乙审')
  const claims = new Map()
  for (const [target, title] of [[worker, '合成甲审'], [reviewer, '合成乙审']]) {
    host.begin(main, '让「' + title + '」窗口核对合成项目')
    host.end(main)
    const assignment = await host.receive(target)
    assert.equal(assignment.source.bridgeWorkflowKind, 'task')
    const claim = await host.call(target, 'workflow_claim', { id: assignment.source.bridgeWorkflowId })
    assert.equal(claim.duplicate, false)
    claims.set(target, claim)
    host.end(target)
  }

  const text = '请核对甲审任务中的第二份合成样本。'
  host.begin(main, '给合成甲审窗口发消息：' + text)
  assert.deepEqual(await host.call(main, 'workflow_message', {}), { state: 'waiting_for_owner_turn_end' })
  host.end(main)

  const followUp = await host.receive(worker)
  assert.equal(followUp.source.bridgeWorkflowKind, 'conversation')
  assert.equal(followUp.source.bridgeWorkflowId, claims.get(worker).id)
  assert(followUp.content[0].text.endsWith(text))
  const answer = '第二份合成样本已核对。'
  host.reply(worker, answer)
  host.end(worker)

  const response = await host.receive(main)
  assert.equal(response.source.bridgeWorkflowKind, 'conversation')
  assert.equal(response.source.bridgeWorkflowId, claims.get(worker).id)
  assert(response.content[0].text.endsWith(answer))
  host.end(main)
  assert.deepEqual(host.deliveries.map(({ target }) => target), [worker, reviewer, worker, main])
})

test('an explicit natural message to a peer with no active task keeps ordinary delivery', async t => {
  const host = await fixture(t)
  host.rename(worker, '合成甲审')
  host.rename(reviewer, '合成资料')
  host.begin(main, '让「合成甲审」窗口核对合成项目')
  host.end(main)
  const assignment = await host.receive(worker)
  assert.equal(assignment.source.bridgeWorkflowKind, 'task')
  assert.equal((await host.call(worker, 'workflow_claim', { id: assignment.source.bridgeWorkflowId })).duplicate, false)
  host.end(worker)

  const text = '这是发往没有委托的窗口的合成消息。'
  host.begin(main, '给合成资料窗口发消息：' + text)
  assert.deepEqual(await host.call(main, 'workflow_message', {}), { state: 'waiting_for_owner_turn_end' })
  host.end(main)
  const message = await host.receive(reviewer)
  assert(message.source.bridgeReceiptKey)
  assert.equal(message.source.bridgeWorkflowKind, undefined)
  assert(message.content[0].text.endsWith(text))
  host.end(reviewer)
  assert.deepEqual(host.deliveries.map(({ target }) => target), [worker, reviewer])
})
